package com.pcguard.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class AgentApiKeyFilter extends OncePerRequestFilter { @Value("${pcguard.security.agent-api-key:}") String key; @Override protected boolean shouldNotFilter(HttpServletRequest r){return !r.getRequestURI().startsWith("/api/v1/agents/")||key==null||key.isBlank();} @Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain c)throws ServletException,IOException {if(("Bearer "+key).equals(r.getHeader("Authorization")))c.doFilter(r,p);else p.sendError(HttpStatus.UNAUTHORIZED.value(),"Agent authentication required");} }
